import java.util.*;
public class LibraryReturnDesk {
 public static void main(String[] x){Scanner s=new Scanner(System.in);String[] pile=new String[3],line=new String[3];int top=-1,front=0,rear=0,size=0,n=s.nextInt();for(int i=0;i<n;i++){String cmd=s.next(),v=s.hasNext()?s.next():"";switch(cmd){case "RETURN":if(top==2)System.out.println(v+" rejected: pile is full");else{pile[++top]=v;System.out.println(v+" placed on pile");}break;case "SHELVE":if(top<0)System.out.println("pile is empty");else System.out.println("shelved "+pile[top--]);break;case "WAIT":if(size==3)System.out.println(v+" rejected: line is full");else{line[rear]=v;rear=(rear+1)%3;size++;System.out.println(v+" joined the line");}break;case "SERVE":if(size==0)System.out.println("no one waiting");else{System.out.println("served "+line[front]);front=(front+1)%3;size--;}break;}}}
}